import math

def dist(x, y, p):
    """d_p distance between tuples x and y; p may be math.inf."""
    if p < 1:
        raise ValueError("p must be at least 1")
    gaps = [abs(a - b) for a, b in zip(x, y)]
    if p == math.inf:
        return max(gaps)
    return sum(g ** p for g in gaps) ** (1 / p)

def nearest(points, q, p):
    """Index of the point nearest q in d_p (first on a tie)."""
    best = 0
    for k in range(1, len(points)):
        if dist(points[k], q, p) < dist(points[best], q, p):
            best = k
    return best
